<tr class="{{ $kind }}"><th>@if($kind==='ngrs-cluster')<small>CLUSTER</small>@endif{{ $kind==='ngrs-grand'?'GRAND TOTAL':$row['tap'] }}</th>
@foreach(range(1,12) as $m)<td data-ngrs-qty="{{ $row['months'][$m]??0 }}" data-ngrs-recharge="{{ $row['recharge'][$m]??0 }}" data-ngrs-days="{{ $days[$m]??0 }}">{{ \App\Support\NgrsFormat::value($row['months'][$m]??0,$row['recharge'][$m]??0,$days[$m]??0,$summaryView,$summaryMetric) }}</td>@if($comparison&&$m===$comparison['previous'])@php $compareDays=$comparison['previous_available']?(int)substr($comparison['previous_end'],8,2):0; @endphp<td class="ngrs-mom-helper" data-ngrs-qty="{{ $row['compare_trx']??0 }}" data-ngrs-recharge="{{ $row['compare_rech']??0 }}" data-ngrs-days="{{ $compareDays }}">{{ \App\Support\NgrsFormat::value($row['compare_trx']??0,$row['compare_rech']??0,$compareDays,$summaryView,$summaryMetric) }}</td>@endif @endforeach
<td class="ngrs-total" data-ngrs-qty="{{ $row['total'] }}" data-ngrs-recharge="{{ $row['total_recharge']??0 }}" data-ngrs-days="{{ array_sum($days) }}">{{ \App\Support\NgrsFormat::value($row['total'],$row['total_recharge']??0,array_sum($days),$summaryView,$summaryMetric) }}</td>
@foreach(range(2,12) as $m)@php
    $fair=$comparison&&$comparison['month']===$m;
    $previousTrx=$fair?($row['compare_trx']??0):($row['months'][$m-1]??0);
    $previousRecharge=$fair?($row['compare_rech']??0):($row['recharge'][$m-1]??0);
    $previousDays=$fair?($comparison['previous_available']?(int)substr($comparison['previous_end'],8,2):0):($days[$m-1]??0);
    $gap=\App\Support\NgrsFormat::gap($row['months'][$m]??0,$row['recharge'][$m]??0,$days[$m]??0,$previousTrx,$previousRecharge,$previousDays,$summaryView,$summaryMetric);
@endphp<td class="ngrs-summary-gap is-{{ $gap['direction'] }}" data-ngrs-gap data-current-trx="{{ $row['months'][$m]??0 }}" data-current-recharge="{{ $row['recharge'][$m]??0 }}" data-current-days="{{ $days[$m]??0 }}" data-previous-trx="{{ $previousTrx }}" data-previous-recharge="{{ $previousRecharge }}" data-previous-days="{{ $previousDays }}">{{ $gap['text'] }}</td>@endforeach</tr>
